# 方法一：DFS 遞迴（推薦，簡潔）
class Solution:
    def cloneGraph(self, node: Optional['Node']) -> Optional['Node']:
        visited = {}     # 原節點 -> 新節點

        def dfs(cur):
            if not cur:
                return None
            if cur in visited:
                return visited[cur]      # 已複製過，直接回傳

            copy = Node(cur.val)
            visited[cur] = copy          # 關鍵：先登記，再遞迴

            for nb in cur.neighbors:
                copy.neighbors.append(dfs(nb))
            return copy

        return dfs(node)


# 方法二：BFS 迭代
class Solution:
    def cloneGraph(self, node: Optional['Node']) -> Optional['Node']:
        if not node:
            return None
        from collections import deque

        visited = {node: Node(node.val)}
        queue = deque([node])

        while queue:
            cur = queue.popleft()
            for nb in cur.neighbors:
                if nb not in visited:
                    visited[nb] = Node(nb.val)   # 複製新節點
                    queue.append(nb)
                # 把新鄰居接上
                visited[cur].neighbors.append(visited[nb])

        return visited[node]

